def tokens(text):
    import unicodedata
    return unicodedata.normalize("NFC", text).casefold().split()

def masked_mean(values, mask):
    kept = [v for v,m in zip(values, mask) if m]
    return sum(kept)/len(kept) if kept else None

def attention_score(query, key):
    from math import sqrt
    return sum(a*b for a,b in zip(query,key))/sqrt(len(key))

def perplexity(losses):
    from math import exp
    return exp(sum(losses)/len(losses)) if losses else None
